import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.CmvPqeTF.js";const _=JSON.parse('{"title":"端口转发","description":"","frontmatter":{},"headers":[],"relativePath":"guide/port-forwarding.md","filePath":"guide/port-forwarding.md","lastUpdated":1788361893000}'),o={name:"guide/port-forwarding.md"};function l(i,t,n,h,s,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="端口转发" tabindex="-1">端口转发 <a class="header-anchor" href="#端口转发" aria-label="Permalink to &quot;端口转发&quot;">​</a></h1><p>侧栏第四个图标（分享/分流形状）是端口转发面板：按连接分组的转发规则管理，支持本地端口转发（SSH 隧道）。</p><hr><h2 id="_1-面板结构" tabindex="-1">1. 面板结构 <a class="header-anchor" href="#_1-面板结构" aria-label="Permalink to &quot;1. 面板结构&quot;">​</a></h2><p>规则<strong>按连接分组</strong>折叠展示（<code>NCollapse</code>），分组标题为「连接名 · 主机」，右侧显示规则数。每条规则显示：</p><ul><li>类型标签（本地转发 / 远程转发 / 动态转发）</li><li>名称、本地 <code>host:port</code> → 远程 <code>host:port</code></li><li>状态标签：<strong>运行中 / 已停止</strong></li><li>hover 操作：▶ 启动 / ■ 停止、✏️ 编辑、🗑 删除（需确认）</li></ul><h2 id="_2-添加-编辑规则" tabindex="-1">2. 添加 / 编辑规则 <a class="header-anchor" href="#_2-添加-编辑规则" aria-label="Permalink to &quot;2. 添加 / 编辑规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>如「MySQL 隧道」</td></tr><tr><td>连接</td><td>下拉选择（显示 <code>名称 (主机)</code>）</td></tr><tr><td>服务预设</td><td>选中自动填充地址四项，见下表</td></tr><tr><td>类型</td><td>本地 / 远程 / 动态</td></tr><tr><td>本地地址 + 本地端口</td><td>监听端</td></tr><tr><td>远程地址 + 远程端口</td><td>目标端</td></tr><tr><td>自动启动</td><td>勾选后保存即启动</td></tr></tbody></table><h3 id="服务预设" tabindex="-1">服务预设 <a class="header-anchor" href="#服务预设" aria-label="Permalink to &quot;服务预设&quot;">​</a></h3><table tabindex="0"><thead><tr><th>预设</th><th>本地</th><th>远程</th></tr></thead><tbody><tr><td>SSH</td><td>127.0.0.1:2222</td><td>127.0.0.1:22</td></tr><tr><td>HTTP</td><td>8080</td><td>80</td></tr><tr><td>HTTPS</td><td>8443</td><td>443</td></tr><tr><td>MySQL</td><td>3306</td><td>3306</td></tr><tr><td>PostgreSQL</td><td>5432</td><td>5432</td></tr><tr><td>Redis</td><td>6379</td><td>6379</td></tr><tr><td>MongoDB</td><td>27017</td><td>27017</td></tr></tbody></table><h2 id="_3-运行机制" tabindex="-1">3. 运行机制 <a class="header-anchor" href="#_3-运行机制" aria-label="Permalink to &quot;3. 运行机制&quot;">​</a></h2><ul><li><strong>本地转发</strong>：在本地 <code>net.Listen</code> 监听，每个入站连接经 SSH 隧道 <code>Dial</code> 到远端 <code>remoteHost:remotePort</code>，双向拷贝流量</li><li>启动时若该连接尚无活跃 SSH 客户端（如未开终端），会自动建立<strong>仅供转发</strong>的 SSH 连接</li><li>停止该连接的最后一条转发规则、且没有终端会话时，空闲的 SSH 连接会被自动回收</li><li>断开连接（如 <code>⌘W</code>）会一并停掉该连接的全部转发</li></ul><h2 id="_4-当前边界-如实说明" tabindex="-1">4. 当前边界（如实说明） <a class="header-anchor" href="#_4-当前边界-如实说明" aria-label="Permalink to &quot;4. 当前边界（如实说明）&quot;">​</a></h2><ul><li><strong>仅「本地转发」已实现</strong>：选择「远程转发」或「动态转发」保存后可以，但<strong>启动时会报错</strong> <code>forward type not yet supported</code></li><li>规则运行状态无主动推送，界面上靠查询刷新</li></ul><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./connections.html">连接与分组管理</a></li><li><a href="./../dev/architecture.html">架构总览</a></li></ul>',17)])])}const p=d(o,[["render",l]]);export{_ as __pageData,p as default};
